/// <summary>
/// Vendor rebate service class
/// </summary>
public final class METVendorRebateService
{

    VendAccount vendAccount;
    METExternalRebateDealReference metExternalRebateDealReference;
    TAMRebateDealId tamRebateDealId;
    TAMRebateFromDate tamRebateFromDate;
    TAMRebateToDate tamRebateToDate;
    TAMRebateActive tamRebateActive;

}

Method.Source:
/// <summary>
/// Collect error
/// </summary>
/// <returns>String</returns>
private str getErrorStr()
{
    SysInfologEnumerator enumerator;
    SysInfologMessageStruct msgStruct;
    Exception exception;
    str error;
    enumerator = SysInfologEnumerator::newData(infolog.cut());
    while (enumerator.moveNext())
    {
        msgStruct = new SysInfologMessageStruct(enumerator.currentMessage());
        exception = enumerator.currentException();
        error = strfmt("%1 %2", error, msgStruct.message());
    }

    return error;
}

/// <summary>
/// Update Vendor Rebate
/// </summary>
/// <param name = "_vendorRebateRequest">METVendorRebateRequest</param>
/// <returns>METVendorRebateResponse</returns>
public METVendorRebateResponse updateVendorRebate(METVendorRebateRequest _vendorRebateRequest)
{
    TAMRebateDeal tamRebateDeal;
    Description255      message;
    container           resultCon;
    METProcessingStatus result;

    changecompany(_vendorRebateRequest.parmDataAreaId())
    {
        try
        {
            ttsbegin;
            select firstonly RecId from tamRebateDeal
                where tamRebateDeal.Deal == _vendorRebateRequest.parmVendorRebateDealContract().parmTAMRebateDealId();

            if (tamRebateDeal)
            {
                resultCon = this.updateDeal(_vendorRebateRequest.parmVendorRebateDealContract());
                result = conPeek(resultCon, 1);
                message = conPeek(resultCon, 2);
                vendAccount= conPeek(resultCon, 3);
                metExternalRebateDealReference = conPeek(resultCon, 4);
                tamRebateDealId = conPeek(resultCon, 5);
                tamRebateFromDate = conPeek(resultCon, 6);
                tamRebateToDate = conPeek(resultCon, 7);
                tamRebateActive = conPeek(resultCon, 8);
            }
            else
            {
                result = METProcessingStatus::Error;
                message = "@MET:VendRebateOldDealExist";
            }

            ttscommit;
        }
        catch(Exception::CLRError)
        {
            System.Exception interopException = CLRInterop::getLastException();

            result = METProcessingStatus::Error;
            message = interopException.ToString();
        }
    }

    return METVendorRebateResponse::newFromParameters(result, message, vendAccount, metExternalRebateDealReference, tamRebateDealId, tamRebateFromDate, tamRebateToDate, tamRebateActive);
}

/// <summary>
/// Create Vendor Rebate
/// </summary>
/// <param name = "_vendorRebateRequest">METVendorRebateRequest</param>
/// <returns>METVendorRebateResponse</returns>
public METVendorRebateResponse createVendorRebate(METVendorRebateRequest _vendorRebateRequest)
{
    TAMRebateDeal tamRebateDeal, tamRebateDealWorkflow;
    METVendorRebateTableContract metVendorRebateTableContract;
    List tamRebateTableList;
    ListIterator literator;
    Description255 message;
    container   resultCon;
    METProcessingStatus result;

    changecompany(_vendorRebateRequest.parmDataAreaId())
    {
        try
        {
            ttsbegin;
            select firstonly RecId from tamRebateDeal
                where tamRebateDeal.METExternalRebateDealReference == _vendorRebateRequest.parmVendorRebateDealContract().parmMETExternalRebateDealReference();

            if (!tamRebateDeal)
            {
                resultCon = this.createHeader(_vendorRebateRequest.parmVendorRebateDealContract());
                result = conPeek(resultCon, 1);
                message = conPeek(resultCon, 2);
                tamRebateDealWorkflow = conPeek(resultCon, 3);
                vendAccount= conPeek(resultCon, 4);
                metExternalRebateDealReference = conPeek(resultCon, 5);
                tamRebateDealId = conPeek(resultCon, 6);
                tamRebateFromDate = conPeek(resultCon, 7);
                tamRebateToDate = conPeek(resultCon, 8);
                tamRebateActive = conPeek(resultCon, 9);
                if (result == METProcessingStatus::Success)// If Rebate deal is created then create other records
                {
                    tamRebateTableList = _vendorRebateRequest.parmMETVendorRebateTableContractArray();
                    if (tamRebateTableList)
                    {
                        literator = new ListIterator(tamRebateTableList);
                        while (literator.more())
                        {
                            metVendorRebateTableContract = literator.value();
                            resultCon = this.createRebateTable(metVendorRebateTableContract);
                            result = conPeek(resultCon, 1);
                            message += conPeek(resultCon, 2);
                            literator.next();
                        }
                        if(result == METProcessingStatus::Success) // Once agreement header and lines are created submit the workflow
                        {
                            this.submitWorkflow(tamRebateDealWorkflow);
                        }
                    }
                }                    
            }
            else
            {
                result = METProcessingStatus::Error;
                message = "@MET:VendRebateNewDealExist";
            }

            ttscommit;
        }
        catch(Exception::CLRError)
        {
            System.Exception interopException = CLRInterop::getLastException();

            result = METProcessingStatus::Error;
            message = interopException.ToString();
        }
    }

    return METVendorRebateResponse::newFromParameters(result, message, vendAccount, metExternalRebateDealReference, tamRebateDealId, tamRebateFromDate, tamRebateToDate, tamRebateActive);
}

/// <summary>
/// Submit workflow
/// </summary>
/// <param name = "_tamRebateDeal">TAMRebateDeal</param>
public void submitWorkflow(TAMRebateDeal _tamRebateDeal)
{
    TAMRebateTable tamRebateTable;
    TAMRebateDeal tamRebateDeal = _tamRebateDeal, tamRebateDealUpdate;       

    select firstonly RecId from tamRebateTable 
        where tamRebateTable.RebateDeal == _tamRebateDeal.RecId
        && tamRebateTable.METAutoApproval == NoYes::No;

    if (tamRebateDeal && !tamRebateTable)
    {
        // Check whether we have an active workflow on the table.
        WorkflowVersionTable workflowVersionTable = Workflow::findWorkflowConfigToActivateForType(workFlowTypeStr(TAMRebateDeal),tamRebateDeal.RecId,tamRebateDeal.TableId);

        // If workflow is active, then submit the workflow.
        if (tamRebateDeal.RecId && workflowVersionTable.RecId)
        {
            // Submitting to workflow
            Workflow::activateFromWorkflowType(workFlowTypeStr(TAMRebateDeal),tamRebateDeal.RecId,"@AccountsPayable:VendBankAccountChangeProposalWorkflow_Submited",false,curUserid());

            // Update revision workflow status to submitted
            tamRebateDealUpdate = TAMRebateDeal::find(tamRebateDeal.RecId,true);
            tamRebateDealUpdate.State = TAMRebateDealWorkflowState::Submitted;
            tamRebateDealUpdate.update();
        }
    }
}

/// <summary>
/// Update Vendor Rebate Deal
/// </summary>
/// <param name = "_metVendorRebateDealContract">METVendorRebateDealContract</param>
/// <returns>container</returns>
public container updateDeal(METVendorRebateDealContract _metVendorRebateDealContract)
{
    #OCCRetryCount
    METProcessingStatus result;
    Description255  message;
    TAMRebateDeal tamRebateDeal;
    TAMRebateDate tamRebateDateUpdate;
    TAMRebateTable tamRebateTableUpdate;

    try
    {
        select firstonly forupdate tamRebateDeal where tamRebateDeal.Deal == _metVendorRebateDealContract.parmTAMRebateDealId();
        tamRebateDeal.RebateToDate = _metVendorRebateDealContract.parmTAMRebateToDate();
        tamRebateDeal.update();
        update_recordSet tamRebateDateUpdate
            setting RebateToDate = tamRebateDeal.RebateToDate
            exists join tamRebateTableUpdate
            where tamRebateTableUpdate.RebateId == tamRebateDateUpdate.RebateId
            && tamRebateTableUpdate.RebateDeal == tamRebateDeal.RecId;

        result = METProcessingStatus::Success;
        message = "@SYS315570";
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                result = METProcessingStatus::Error;
                message = this.getErrorStr();
            }
            else
            {
                retry;
            }
        }
        else
        {
            result = METProcessingStatus::Error;
            message = this.getErrorStr();
        }
    }
    catch
    {
        result = METProcessingStatus::Error;
        message = this.getErrorStr();
    }

    return [result, message, tamRebateDeal.METVendAccount, tamRebateDeal.METExternalRebateDealReference, tamRebateDeal.Deal, tamRebateDeal.RebateFromDate, tamRebateDeal.RebateToDate, tamRebateDeal.RebateActive];

}

/// <summary>
/// Create Vendor Deal
/// </summary>
/// <param name = "_metVendorRebateDealContract">METVendorRebateDealContract</param>
/// <returns>container</returns>
public container createHeader(METVendorRebateDealContract _metVendorRebateDealContract)
{
    #OCCRetryCount
    METProcessingStatus result;
    Description255  message;
    TAMRebateDeal tamRebateDeal;        

    try
    {
        tamRebateDeal.StatusId = TAMRebateParameters::find().DefaultRebateStatusId;
        tamRebateDeal.RebateActive = NoYes::Yes;
        tamRebateDeal.State = TAMRebateDealWorkflowState::Draft;
        if(_metVendorRebateDealContract.parmTAMRebateDealId())        
        {
            tamRebateDeal.Deal = _metVendorRebateDealContract.parmTAMRebateDealId();
        }
        else
        {
            tamRebateDeal.Deal = NumberSeq::newGetNum(TAMRebateParameters::numRefRebateDealId(), false).num();
        }       

        tamRebateDeal.ModuleInventCustVend = _metVendorRebateDealContract.parmModuleInventCustVend();
        tamRebateDeal.RebateCurrencyCode = _metVendorRebateDealContract.parmTAMRebateCurrencyCode();
        tamRebateDeal.Description = _metVendorRebateDealContract.parmDescription();
        tamRebateDeal.METVendAccount = _metVendorRebateDealContract.parmVendAccount();
        tamRebateDeal.RebateOutputType = _metVendorRebateDealContract.parmTAMRebateOutputType();
        tamRebateDeal.RebateReconciliation = _metVendorRebateDealContract.parmTAMRebateReconciliation();
        tamRebateDeal.RebateType = _metVendorRebateDealContract.parmTAMRebateType();
        tamRebateDeal.METExternalRebateDealReference = _metVendorRebateDealContract.parmMETExternalRebateDealReference();
        tamRebateDeal.METUseExternalSellData = _metVendorRebateDealContract.parmMETUseExternalSellData();
        tamRebateDeal.RebatePostingId = _metVendorRebateDealContract.parmTAMRebatePostingId();
        tamRebateDeal.RebateFromDate = _metVendorRebateDealContract.parmTAMRebateFromDate();
        tamRebateDeal.RebateToDate = _metVendorRebateDealContract.parmTAMRebateToDate();
        tamRebateDeal.insert();
        result = METProcessingStatus::Success;
        message = strFmt("@MET:RebateDealCreated",tamRebateDeal.Deal);

    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                result = METProcessingStatus::Error;
                message = this.getErrorStr();
            }
            else
            {
                retry;
            }
        }
        else
        {
            result = METProcessingStatus::Error;
            message = this.getErrorStr();
        }
    }
    catch
    {
        result = METProcessingStatus::Error;
        message = this.getErrorStr();
    }

    return [result, message, tamRebateDeal, tamRebateDeal.METVendAccount, tamRebateDeal.METExternalRebateDealReference, tamRebateDeal.Deal, tamRebateDeal.RebateFromDate, tamRebateDeal.RebateToDate, tamRebateDeal.RebateActive];
}

/// <summary>
