/// <summary>
/// Create Rebate date record
/// </summary>
/// <param name = "_metTAMRebateDateContract">METTAMRebateDateContract</param>
/// <param name = "_rebateId">TAMRebateId</param>
/// <returns>container</returns>
public container createRebateDate(METTAMRebateDateContract _metTAMRebateDateContract, TAMRebateId _rebateId)
{
    #OCCRetryCount
    METProcessingStatus result;
    Description255  message;
    TAMRebateDate rebateDate;

    try
    {
        rebateDate.RebateId = _rebateId;
        rebateDate.RebateFromDate = _metTAMRebateDateContract.parmAgreementValidFromDate();
        rebateDate.RebateToDate = _metTAMRebateDateContract.parmAgreementValidToDate();
        rebateDate.RebateClaimBy = _metTAMRebateDateContract.parmClaimPeriodFrequency();
        rebateDate.RebateClaimPer = _metTAMRebateDateContract.parmclaimPeriodRecurrence();
        rebateDate.LineNum = _metTAMRebateDateContract.parmLineNumber();
        rebateDate.RebatePeriodCode = _metTAMRebateDateContract.parmProvisionPeriodFrequency();
        rebateDate.RebatePer = _metTAMRebateDateContract.parmProvisionPeriodRecurrence();
        rebateDate.ProcessPosting = _metTAMRebateDateContract.parmWillSourceDocumentPostingCalculateProvision();
        rebateDate.RebateStartingDayOfWeek = _metTAMRebateDateContract.parmProvisionWeekDayPeriodStart();
        rebateDate.insert();
        result = METProcessingStatus::Success;
        message = strFmt("@MET:RebateDateCreated",rebateDate.RebateId);

    }
    catch (Exception::Deadlock)
